import androidx.compose.ui.*
import androidx.compose.ui.res.stringResource

@Composable
fun LinkCopiedScreen(navigate: (String) -> Unit) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.surfaceContainerHigh)
            .verticalScroll(rememberScrollState()),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        StatusBar(time = "5:00", modifier = Modifier.fillMaxWidth())
        PlaylistAppBar(
            title = "Arabic Music Mix",
            aiMixLabel = stringResource(R.string.ai_mix),
            sourceLabel = stringResource(R.string.playlist),
            switch = Switch(),
            onCollapse = { navigate("back") },
            modifier = Modifier.fillMaxWidth(),
        )
        // Artwork Section
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = AppTheme.spacing.spacing48, bottom = AppTheme.spacing.spacing64),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Artwork(image = painterResource(R.drawable.img_115_4967))
        }
        // Track Header
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = AppTheme.spacing.spacing16, end = AppTheme.spacing.spacing8),
            horizontalArrangement = Arrangement.spacedBy(AppTheme.spacing.spacing8),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            TrackMetadata(
                title = "كيفك ع فراقى",
                subtitle = "محمد شاكر وفضل شاكر - كيفك ع فراقى",
                showSubtitleIcon = false,
                subtitleIcon = AppIcons.CloudDone,
                titleStyle = AppTheme.typography.titleLargeEmphasized,
                subtitleStyle = MaterialTheme.typography.bodyMedium,
                titleLines = 1,
                modifier = Modifier.weight(1f),
            )
            IconButton(
                style = IconButtonStyle.Tonal,
                icon = AppIcons.Share,
                onClick = { navigate("share-sheet") },
            )
            IconButton(icon = AppIcons.MoreVert)
        }
        // Progress Section
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = AppTheme.spacing.spacing16, top = AppTheme.spacing.spacing12, end = AppTheme.spacing.spacing16),
        ) {
            PlaybackProgress(
                elapsedTime = "00:03",
                totalTime = "03:48",
                progressIndicator = ProgressIndicator(),
                modifier = Modifier.fillMaxWidth(),
            )
        }
        // Controls Section
        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
                .padding(start = AppTheme.spacing.spacing16, top = AppTheme.spacing.spacing32, end = AppTheme.spacing.spacing16, bottom = AppTheme.spacing.spacing48),
        ) {
            PlaybackControls(modifier = Modifier.fillMaxWidth())
        }
        PlayerUtilityBar(
            lyricsLabel = stringResource(R.string.lyrics),
            queueLabel = stringResource(R.string.queue),
            audioLabel = stringResource(R.string.audio),
            iconLyrics = AppIcons.Lyrics,
            iconQueueMusic = AppIcons.QueueMusic,
            iconGraphicEq = AppIcons.Settings,
            onChange = { index -> when (index) { "Lyrics" -> navigate("lyrics"); "None" -> navigate("now-playing") } },
            modifier = Modifier.fillMaxWidth(),
        )
        Tooltip(text = stringResource(R.string.link_copied))
    }
}

